package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant;
@Document("refunds") public class Refund {
 public enum Status { PENDING, PROCESSING, PROCESSED, COMPLETED, REJECTED }
 @Id private String id; @Indexed private String bookingId; @Indexed private String userId; private double originalAmount; private double refundPercentage; private double refundAmount; private CancellationReason cancellationReason; private Instant cancellationDate=Instant.now(); private Status refundStatus=Status.PENDING; private Instant expectedCompletionDate; private Instant processedDate;
 public String getId(){return id;} public void setId(String v){id=v;} public String getBookingId(){return bookingId;} public void setBookingId(String v){bookingId=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public double getOriginalAmount(){return originalAmount;} public void setOriginalAmount(double v){originalAmount=v;} public double getRefundPercentage(){return refundPercentage;} public void setRefundPercentage(double v){refundPercentage=v;} public double getRefundAmount(){return refundAmount;} public void setRefundAmount(double v){refundAmount=v;} public CancellationReason getCancellationReason(){return cancellationReason;} public void setCancellationReason(CancellationReason v){cancellationReason=v;} public Instant getCancellationDate(){return cancellationDate;} public Status getRefundStatus(){return refundStatus;} public void setRefundStatus(Status v){refundStatus=v;} public Instant getExpectedCompletionDate(){return expectedCompletionDate;} public void setExpectedCompletionDate(Instant v){expectedCompletionDate=v;} public Instant getProcessedDate(){return processedDate;} public void setProcessedDate(Instant v){processedDate=v;}
}
